/* ===================== ルール ===================== */
function guide(){
  setHeader('基本ルール','#/tools');
  const _srcTop=`<a class="row" href="#/sources" style="border-bottom:1px solid var(--line)"><div class="row-m"><div class="row-t">データの出典と確認状況</div><div class="row-s">数値の出どころと、どこまで確かめたか</div></div><span class="chev">${SVG(I.chev,18)}</span></a>${srcLine('formula','regulation','typechart')}`;
  const f=[
    ['タイプ相性の基本','「ばつぐん」かどうかは、攻撃する技のタイプと、受ける側のタイプで決まります。受ける側が2タイプのときは倍率をかけ算し、×2と×2で4倍、×2と×½で等倍になります。効かない組み合わせ（例：でんき技→じめん）は倍率0です。右下の「相性」ボタンから相手を選ぶと、効く技を自動で表示します。'],
    ['バトルの形式','ダブルバトルは6匹を持ち込み、そこから4匹を選出します。シングルバトルは6匹から3匹です。公式大会やランクバトルの中心はダブルバトルです。'],
    ['レベルと個体値','バトル中は全員がLv50に統一され、個体値はすべて31で固定です。個体値を厳選する必要はありません。'],
    ['能力ポイント','従来の努力値にあたる仕組みです。1匹あたり合計<span class="f">66</span>、1つの能力に最大<span class="f">32</span>まで振れます。振った数がそのままLv50のステータスに加算され、1ポイントにつき5VPが必要です。'],
    ['ステータスの計算式','HP＝種族値＋ポイント＋<span class="f">75</span>。ほかの能力＝（種族値＋ポイント＋<span class="f">20</span>）×性格補正（<span class="f">1.1</span>／<span class="f">1.0</span>／<span class="f">0.9</span>）。図鑑の「Lv50計算」タブで試せます。'],
    ['レギュレーション','使えるポケモンや持ち物は期間ごとのレギュレーションで決まります。M-A（4月8日から）、M-B（6月17日から）、M-C（9月9日から）と更新されています。'],
    ['使えるポケモン','基本は最終進化のポケモンのみで、ピカチュウだけが例外です。通常の種とそのメガシンカが対象で、伝説やパラドックスポケモンは含まれません。']];
  V.innerHTML=_srcTop+f.map(([t,d])=>`<section class="art"><h3>${t}</h3><p>${d}</p></section>`).join('')
    +adSlot('記事下')
    +`<p class="note" style="color:var(--mute);padding:4px 16px 0">公開情報をもとにまとめています。アップデートで変わる場合があるため、公式の発表もあわせてご確認ください。</p>`;
}

